// Independent recount, different algorithm: enumerate every calendar day in window,
// classify, then locate the Nth usable day.
const holidays = new Set(["2026-11-20","2026-12-08","2026-12-24","2026-12-25","2026-12-31","2027-01-01","2027-02-08","2027-02-09"]);
const recess = (s)=>{ const d=new Date(s+"T00:00:00Z"); return d>=new Date("2026-12-20T00:00:00Z") && d<=new Date("2027-01-20T00:00:00Z"); };
function usable(iso){ const d=new Date(iso+"T00:00:00Z"); const wd=d.getUTCDay(); return wd>=1&&wd<=5&&!holidays.has(iso)&&!recess(iso); }
function nth(startIso,n){ let d=new Date(startIso+"T00:00:00Z"),c=0,last=null; while(c<n){ const iso=d.toISOString().slice(0,10); if(usable(iso)){c++;last=iso;} d.setUTCDate(d.getUTCDate()+1);} return last; }
// next usable strictly after
function next(iso){ let d=new Date(iso+"T00:00:00Z"); do{ d.setUTCDate(d.getUTCDate()+1);}while(!usable(d.toISOString().slice(0,10))); return d.toISOString().slice(0,10); }
const pubC = next("2026-11-19"), iniC = next(pubC);
const pubS = next("2026-12-10"), iniS = next(pubS);
// publication rule: first usable day strictly after disponibilizacao. But careful: usable() excludes recess;
// in Nov that's irrelevant. For sentenca pub (11/12) also irrelevant.
return {citacao:{pub:pubC,ini:iniC,contest15:nth(nth(iniC,0)||iniC,1)&&nth(iniC,15)}, sentenca:{pub:pubS,ini:iniS,emb5:nth(iniS,5),apel15:nth(iniS,15)}};

